<?php
/**
 * Generates includes/api/endpoint-scopes.php from the gateway's OpenAPI contract.
 *
 * The map records, for every API-key operation the gateway exposes, the app it
 * belongs to and the scopes it demands. Agend_Apps_API::request() consults it to
 * refuse a call the stored key is known not to be allowed to make.
 *
 * Usage (from the repository root, or anywhere):
 *
 *     php agend-apps-core/bin/generate-endpoint-scopes.php /path/to/agend-dashboard/apps/api/openapi.json
 *
 * The generated file is committed; rerun this whenever the gateway adds or
 * changes an endpoint or its scopes (see "Endpoint scope map" in README.md).
 * The output is deterministic, so a rerun against an unchanged contract
 * produces no diff.
 *
 * How the contract is read:
 *
 * - Only `/v1/...` paths are mapped, keyed WITHOUT the `/v1` prefix, because
 *   the plugin's paths are relative to the versioned base URL.
 * - Only `apiKey` security requirements count. Operations secured only by a
 *   user or mobile bearer carry no API key scope and are left out.
 * - The app is the first path segment after `/v1`, as the gateway derives it
 *   (extractAppFromPath in the public-api middleware). A scope whose prefix
 *   disagrees with that segment is reported on stderr.
 * - An operation can list several `security` alternatives. They are kept as
 *   alternatives (any one satisfied is enough), with any alternative that is a
 *   strict superset of another dropped as redundant. Treating them as
 *   alternatives errs toward letting a call through, never toward blocking it.
 *
 * @package Agend_Apps_Core
 */

if ( 'cli' !== PHP_SAPI ) {
	exit( 1 );
}

if ( empty( $argv[1] ) || ! is_readable( $argv[1] ) ) {
	fwrite( STDERR, "Usage: php generate-endpoint-scopes.php <path-to-openapi.json>\n" );
	exit( 1 );
}

$spec = json_decode( (string) file_get_contents( $argv[1] ), true );

if ( ! is_array( $spec ) || empty( $spec['paths'] ) ) {
	fwrite( STDERR, "The file is not an OpenAPI document with paths.\n" );
	exit( 1 );
}

$methods = array( 'get', 'post', 'put', 'patch', 'delete' );
$map     = array();

foreach ( $spec['paths'] as $full_path => $operations ) {
	if ( 0 !== strpos( $full_path, '/v1/' ) ) {
		continue;
	}

	$path     = substr( $full_path, 3 );
	$segments = explode( '/', trim( $path, '/' ) );
	$app      = $segments[0];

	foreach ( $operations as $method => $operation ) {
		if ( ! in_array( $method, $methods, true ) || empty( $operation['security'] ) ) {
			continue;
		}

		$alternatives = array();

		foreach ( $operation['security'] as $requirement ) {
			if ( ! isset( $requirement['apiKey'] ) ) {
				continue;
			}

			$scopes = array_values( array_unique( array_map( 'strval', $requirement['apiKey'] ) ) );
			sort( $scopes );
			$alternatives[ implode( ' ', $scopes ) ] = $scopes;
		}

		if ( ! $alternatives ) {
			continue;
		}

		$alternatives = array_values( $alternatives );

		// Drop an alternative that contains every scope of another one: the
		// smaller set already satisfies it.
		$alternatives = array_values(
			array_filter(
				$alternatives,
				static function ( array $candidate ) use ( $alternatives ): bool {
					foreach ( $alternatives as $other ) {
						if ( $other !== $candidate && ! array_diff( $other, $candidate ) ) {
							return false;
						}
					}
					return true;
				}
			)
		);

		foreach ( $alternatives as $scopes ) {
			foreach ( $scopes as $scope ) {
				if ( 0 !== strpos( $scope, $app . '.' ) ) {
					fwrite( STDERR, sprintf( "Note: %s %s requires %s, which is not an %s scope.\n", strtoupper( $method ), $path, $scope, $app ) );
				}
			}
		}

		$map[ strtoupper( $method ) . ' ' . $path ] = array(
			'app'    => $app,
			'scopes' => $alternatives,
		);
	}
}

ksort( $map );

$out  = "<?php\n";
$out .= "/**\n";
$out .= " * Endpoint scope map: the app and API key scopes each gateway endpoint requires.\n";
$out .= " *\n";
$out .= " * GENERATED by bin/generate-endpoint-scopes.php from the gateway's openapi.json.\n";
$out .= " * Do not edit by hand; rerun the generator instead.\n";
$out .= " *\n";
$out .= " * Keys are `METHOD /path` relative to the /v1 base URL. `scopes` is a list of\n";
$out .= " * alternatives: the key may call the endpoint when it holds every scope of any\n";
$out .= " * one alternative.\n";
$out .= " *\n";
$out .= " * @package Agend_Apps_Core\n";
$out .= " */\n\n";
$out .= "if ( ! defined( 'ABSPATH' ) ) {\n\texit;\n}\n\n";
$out .= "return array(\n";

foreach ( $map as $key => $entry ) {
	$alts = array();

	foreach ( $entry['scopes'] as $scopes ) {
		$alts[] = 'array( ' . implode( ', ', array_map( static fn( $s ) => var_export( $s, true ), $scopes ) ) . ' )';
	}

	$out .= sprintf(
		"\t%s => array(\n\t\t'app'    => %s,\n\t\t'scopes' => array( %s ),\n\t),\n",
		var_export( $key, true ),
		var_export( $entry['app'], true ),
		implode( ', ', $alts )
	);
}

$out .= ");\n";

$target = dirname( __DIR__ ) . '/includes/api/endpoint-scopes.php';
file_put_contents( $target, $out );

fwrite( STDOUT, sprintf( "Wrote %d endpoints to %s\n", count( $map ), $target ) );
